/**
 * tests/glass_parity.js — property-model parity vs PNNL-35884 Tables 3-5/3-6.
 *
 * The full application verifies its models by reproducing the paper's
 * Table 3-6 properties from the Table 3-4 formulations.  This test runs the
 * same check through the JS port: if the JS evaluate() matches the paper to
 * the same 1–4% tolerance the Python model achieves, the port is faithful.
 *
 * Also cross-checks directly against the full app's Python output (fixture
 * generated by tools/gen_parity_fixtures.py) for exactness.
 *
 * Run: node tests/glass_parity.js
 */
'use strict';
const fs = require('fs');
const path = require('path');
const Glass = require('../web/js/engine/glass.js');

const FIXTURE_DIR = path.join(__dirname, 'fixtures');

let passed = 0, failed = 0;
function check(name, cond, extra) {
  if (cond) passed++;
  else { failed++; console.error(`FAIL: ${name}`, extra || ''); }
}
function close(a, b, rel) {
  return Math.abs(a - b) <= rel * Math.max(Math.abs(a), Math.abs(b), 1e-12);
}

// Paper Table 3-4 formulations (oxide fractions of glass from each component)
const T34 = {
  Batch3:  { Waste: 0.486333, BoricAcid: 0.219716, Li2CO3: 0.013759, Silica: 0.240252, Zincite: 0.039941 },
  Batch17: { Waste: 0.221299, Kyanite: 0.009249, BoricAcid: 0.066234, Wollastonite: 0.213945,
             Na2CO3: 0.047149, Li2CO3: 0.003212, Cr2O3: 0.001655, Silica: 0.386448, V2O5: 0.050809 },
  Batch45: { Waste: 0.400059, Kyanite: 0.101709, BoricAcid: 0.105393, Cr2O3: 0.005614,
             Silica: 0.34796, Zincite: 0.039265 },
};
// Paper Table 3-6 no-uncertainty targets
const T36 = {
  Batch3:  { NL: 1.01, eta1150: 5.71, k3: 0.004 },
  Batch17: { NL: 1.40, eta1150: 4.13, k3: 0.032 },
  Batch45: { NL: 1.61, eta1150: 5.82, k3: 0.035 },
};

// Example waste vectors come from the extracted dataset (same as ewg/gfc.py)
const dataPath = path.join(__dirname, '..', 'web', 'data', 'mission_data.json');
const DATA = JSON.parse(fs.readFileSync(dataPath, 'utf8'));
const EXAMPLE_WASTES = DATA.gfc.example_wastes;

// The full app's Python evaluate() loads its Appendix-C covariance at import
// time, so its pass/fail includes Upred margins.  Load the same matrices into
// the JS port BEFORE any parity comparison (order matters).
Glass.setCovariance(DATA.covariance);

// reproduce glass composition: x = component fractions; M rows per the
// Table 3-4 convention (waste row normalized, GFC rows normalized)
function glassFromRecipe(waste, recipe) {
  const names = ['Waste', ...Glass.GFC_NAMES];
  const M = Glass.buildRows(waste);
  const x = names.map(nm => recipe[nm] || 0);
  return Glass.glassOf(x, M);
}

// ---- 1. property reproduction ---------------------------------------
// NOTE: Batch45 is a KNOWN data-provenance exception in the full app
// (hanford-glass-mission-modeling skill, pitfalls): its BBI-derived waste
// vector carries Al2O3 ~6% high vs the paper's DWPF PEWASTE, giving NL
// 1.37 / η 6.11 in the full app vs paper 1.61 / 5.82 — Batch3/17 stay
// exact.  The sandbox inherits the same vector, so we assert Batch45
// against the FULL APP's output (fixture), not the paper's.
const PY_BATCH45 = { NL: 1.365281, eta1150: 6.113660 };   // full-app output (data-provenance exception)
for (const batch of Object.keys(T34)) {
  const waste = EXAMPLE_WASTES[batch];
  const g = glassFromRecipe(waste, T34[batch]);
  const ev = Glass.evaluate(g);
  const target = batch === 'Batch45' ? PY_BATCH45 : T36[batch];
  const nlTol = batch === 'Batch45' ? 0.02 : 0.04;
  const etaTol = batch === 'Batch45' ? 0.02 : 0.02;
  check(`${batch} NL within ${Math.round(nlTol*100)}%`, close(ev.NL, target.NL, nlTol),
        `JS ${ev.NL.toFixed(3)} vs ${batch === 'Batch45' ? 'app' : 'paper'} ${target.NL}`);
  check(`${batch} eta1150 within ${Math.round(etaTol*100)}%`, close(ev.eta1150, target.eta1150, etaTol),
        `JS ${ev.eta1150.toFixed(3)} vs ${batch === 'Batch45' ? 'app' : 'paper'} ${target.eta1150}`);
  check(`${batch} k1208 within 15%`,
        close(ev.k1208, (batch === 'Batch45' ? 0.031937 : T36[batch].k3), 0.15),
        `JS ${ev.k1208.toFixed(4)} vs ${batch === 'Batch45' ? 'app' : 'paper'} ${(batch === 'Batch45' ? 0.031937 : T36[batch].k3)}`);
}

// ---- 2. exact parity with the full app's Python evaluate() ----------
const pyFixtures = path.join(FIXTURE_DIR, 'glass_parity_python.json');
if (fs.existsSync(pyFixtures)) {
  const fx = JSON.parse(fs.readFileSync(pyFixtures, 'utf8'));
  for (const case_ of fx.cases) {
    const ev = Glass.evaluate(case_.glass);
    for (const [prop, target] of Object.entries(case_.expected)) {
      const got = ev[prop];
      check(`${case_.name} ${prop} matches Python`,
            Math.abs(got - target) <= 1e-6 * Math.max(1, Math.abs(target)),
            `JS ${got} vs Py ${target}`);
    }
  }
} else {
  console.log('(Python parity fixture missing — generating it requires the full app)');
}

// ---- 3. Upred margins active with covariance -------------------------
{
  const covPath = path.join(FIXTURE_DIR, 'covariance_fixt.json');
  if (fs.existsSync(covPath)) {
    const cov = JSON.parse(fs.readFileSync(covPath, 'utf8'));
    Glass.setCovariance(cov);
    const waste = EXAMPLE_WASTES.Batch3;
    const g = glassFromRecipe(waste, T34.Batch3);
    const ev = Glass.evaluate(g);
    check('Upred pct > 0', ev.upred.pct > 0, ev.upred);
    check('Upred eta1150 > 0', ev.upred.eta1150 > 0, ev.upred);
    check('Upred k1208 > 0', ev.upred.k1208 > 0, ev.upred);
    check('Upred wso3 > 0', ev.upred.wso3 > 0, ev.upred);
    // compare against Python upred values if fixture present
    const pyUp = path.join(FIXTURE_DIR, 'upred_parity_python.json');
    if (fs.existsSync(pyUp)) {
      const fx = JSON.parse(fs.readFileSync(pyUp, 'utf8'));
      for (const c of fx.cases) {
        const g2 = c.glass;
        const ev2 = Glass.evaluate(g2);
        for (const [k, target] of Object.entries(c.expected)) {
          check(`${c.name} upred.${k} matches Python (~1%)`,
                Math.abs(ev2.upred[k] - target) <= 0.011 * Math.max(target, 1e-9),
                `JS ${ev2.upred[k]} vs Py ${target}`);
        }
      }
    }
  } else {
    console.log('(covariance fixture missing — Upred check skipped)');
  }
}

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed ? 1 : 0);
